import{_ as n,o as t,c as r,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"ZP10: Notenbildung und mündliche Prüfung","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/zp10-rechtsstand.md","filePath":"zeugnisse/zp10-rechtsstand.md"}'),i={name:"zeugnisse/zp10-rechtsstand.md"};function a(h,e,u,d,l,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="zp10-notenbildung-und-mundliche-prufung" tabindex="-1">ZP10: Notenbildung und mündliche Prüfung <a class="header-anchor" href="#zp10-notenbildung-und-mundliche-prufung" aria-label="Permalink to &quot;ZP10: Notenbildung und mündliche Prüfung&quot;">​</a></h1><p>Diese Hinweise betreffen das Abschlussverfahren nach <strong>APO-S I</strong>. Für mündliche Prüfungen gilt seit <strong>1. August 2026</strong> die Neufassung des § 34.</p><h2 id="teilnahme-und-notenfestsetzung" tabindex="-1">Teilnahme und Notenfestsetzung <a class="header-anchor" href="#teilnahme-und-notenfestsetzung" aria-label="Permalink to &quot;Teilnahme und Notenfestsetzung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Abweichung zwischen Vornote und schriftlicher Prüfungsnote</th><th>Verfahren</th></tr></thead><tbody><tr><td>Keine</td><td>Die übereinstimmende Note bildet die Abschlussnote.</td></tr><tr><td>Eine Notenstufe</td><td>Die Fachlehrkraft legt die Abschlussnote unter Berücksichtigung der Zweitkorrektur fest.</td></tr><tr><td>Mehr als eine Notenstufe</td><td>Eine mündliche Prüfung findet auf Wunsch statt. Ohne sie setzt die Fachlehrkraft die Abschlussnote unter Berücksichtigung der Zweitkorrektur fest.</td></tr></tbody></table><p>Eine große Abweichung löst damit für sich genommen keine Pflichtprüfung mehr aus. Rechtsgrundlage: <a href="https://bass.schule.nrw/20249.htm" target="_blank" rel="noreferrer">§ 34 APO-S I und Änderung zum 1. August 2026</a>.</p><h2 id="abschlussnote-und-nachprufung-unterscheiden" tabindex="-1">Abschlussnote und Nachprüfung unterscheiden <a class="header-anchor" href="#abschlussnote-und-nachprufung-unterscheiden" aria-label="Permalink to &quot;Abschlussnote und Nachprüfung unterscheiden&quot;">​</a></h2><p>Ohne mündliche Prüfung zählen Vor- und Prüfungsnote jeweils zur Hälfte. Mit mündlicher Prüfung gilt die Gewichtung <strong>5 : 3 : 2</strong>. Nur für diesen Fall sieht § 32 Absatz 3 bei einer Dezimalstelle bis einschließlich 5 die bessere Note vor.</p><p>Eine <strong>Nachprüfung zum nachträglichen Erwerb eines Abschlusses</strong> ist ein anderes Verfahren; in einem ZP10-Prüfungsfach ist sie nach § 44 Absatz 3 ausgeschlossen. Siehe <a href="https://bass.schule.nrw/12691.htm" target="_blank" rel="noreferrer">§§ 32 und 44 APO-S I</a>.</p><h2 id="in-schild-nrw-bearbeiten" tabindex="-1">In SchILD-NRW bearbeiten <a class="header-anchor" href="#in-schild-nrw-bearbeiten" aria-label="Permalink to &quot;In SchILD-NRW bearbeiten&quot;">​</a></h2><p>Die geänderten ZP10-Regeln sind in SchILD-NRW erfassbar. Übernehmen Sie zunächst die vollständigen Vor- und Prüfungsnoten. Erfassen Sie gewünschte mündliche Prüfungen im Reiter <strong>ZP 10/ZK</strong> und anschließend deren Ergebnisse. Prüfen beziehungsweise ergänzen Sie die Abschlussnoten entsprechend der fachlichen Notenfestsetzung und übernehmen Sie diese in die Leistungsdaten. Die älteren Bildschirmabbildungen können frühere Prüfungsmarkierungen zeigen; sie begründen keine heutige Pflichtprüfung.</p><p>Zurück zu <a href="/zeugnisse/zp10.html">ZP10 vorbereiten und bearbeiten</a>.</p>',11)])])}const f=n(i,[["render",a]]);export{g as __pageData,f as default};
